class Fridge:
    def __init__(self):
        self._items = {}

    def add(self, name, qty):
        if qty <= 0:
            raise ValueError("quantity must be positive")
        self._items[name] = self._items.get(name, 0) + qty

    def remove(self, name, qty):
        if qty <= 0:
            raise ValueError("quantity must be positive")
        available = self._items.get(name, 0)
        if available < qty:
            raise ValueError(
                f"cannot remove {qty} {name}: only {available} available"
            )
        self._items[name] = available - qty
        if self._items[name] == 0:
            del self._items[name]

    def __contains__(self, name):
        return name in self._items

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(sorted(self._items))

    def __repr__(self):
        return f"Fridge({len(self)} items)"


fridge = Fridge()
fridge.add("eggs", 6)
fridge.add("milk", 1)
fridge.add("eggs", 6)
print("eggs" in fridge, len(fridge))   # True 2
print(list(fridge))                    # ['eggs', 'milk']
fridge.remove("eggs", 12)
print("eggs" in fridge)                # False
fridge.remove("milk", 5)
# ValueError: cannot remove 5 milk: only 1 available
```

L'intérêt des dunders est dans le code **appelant** : `"eggs" in fridge` se lit comme la question qu'on se pose, au lieu de `fridge.contains("eggs")`, et `list(fridge)` fonctionne parce que `__iter__` délègue à `iter()` sur la liste triée des clés. La classe encapsule par ailleurs les invariants (jamais de quantité négative, jamais de clé à 0) qu'un dict nu ne garantissait pas à l'exercice 2 du chapitre précédent — c'est exactement le passage « données brutes → objet métier ».

